-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.no_plan_json(p_world uuid, p_x double precision, p_y double precision, p_range double precision)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
      'building', m.building, 'level', m.level, 'x', m.x, 'y', m.y, 'dir', m.dir) order by m.level, m.dir, m.x, m.y), '[]'::jsonb)
    from no_plan_side m
   where m.world_id = p_world
     and greatest(abs(m.x + 0.5 - p_x), abs(m.y + 0.5 - p_y)) <= p_range
$function$
